window.products.push({"id":211964,"name":"XPOWER XD-125 125-Pint Commercial Dehumidifier with Automatic Purge Pump and Drainage Hose","category":"homeandappliances","retail price":1390.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61fLHXMovIL._AC_SL1000_.jpg","description":"XPOWER XD-125 125-Pint Commercial Dehumidifier with Automatic Purge Pump and Drainage Hose ACCELERATE DRYING Commercial dehumidifiers are capable of extracting moisture at an accelerated pace, compared to the retail version. When there is flooding or water leakage, use a commercial to dispose of moisture quickly before mold comes to life. The XD-125 is capable of removing 125 Pints/Day or 15 Gallons/day in a completely saturated environment (90F, 90% RH), and 76 Pints/Day or 9.5 gallons/day at AHAM Standards (80F, 60% RH). Dry the area fast before mold or mildew forms!","images":["https://m.media-amazon.com/images/I/61fLHXMovIL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"XPOWER","source_asin":"B01MRF98PT","category_path":"Home & Kitchen"},"sku":"BM-211964","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01MRF98PT","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01MRF98PT","price_pending":true,"merchant_ready":false});
